using MediaProcessingApi.Entities;

namespace MediaProcessingApi.Services;

public class InMemoryStore
{
    private readonly Dictionary<string, Application> _applications = new();
    private readonly Dictionary<string, MediaFile> _files = new();
    private readonly Dictionary<string, VideoSegment> _segments = new();
    private readonly Dictionary<string, ProcessingJob> _jobs = new();
    private readonly object _lock = new();

    public Application? GetApplication(string id)
    {
        lock (_lock)
        {
            return _applications.TryGetValue(id, out var app) ? app : null;
        }
    }

    public void AddApplication(Application application)
    {
        lock (_lock)
        {
            _applications[application.Id] = application;
        }
    }

    public void UpdateApplication(Application application)
    {
        lock (_lock)
        {
            _applications[application.Id] = application;
        }
    }

    public MediaFile? GetFile(string id)
    {
        lock (_lock)
        {
            return _files.TryGetValue(id, out var file) ? file : null;
        }
    }

    public void AddFile(MediaFile file)
    {
        lock (_lock)
        {
            _files[file.Id] = file;
        }
    }

    public void UpdateFile(MediaFile file)
    {
        lock (_lock)
        {
            _files[file.Id] = file;
        }
    }

    public List<VideoSegment> GetSegmentsByApplicationId(string applicationId)
    {
        lock (_lock)
        {
            return _segments.Values.Where(s => s.ApplicationId == applicationId).ToList();
        }
    }

    public void AddSegment(VideoSegment segment)
    {
        lock (_lock)
        {
            _segments[segment.Id] = segment;
        }
    }

    public void UpdateSegment(VideoSegment segment)
    {
        lock (_lock)
        {
            _segments[segment.Id] = segment;
        }
    }

    public ProcessingJob? GetJob(string id)
    {
        lock (_lock)
        {
            return _jobs.TryGetValue(id, out var job) ? job : null;
        }
    }

    public void AddJob(ProcessingJob job)
    {
        lock (_lock)
        {
            _jobs[job.Id] = job;
        }
    }

    public void UpdateJob(ProcessingJob job)
    {
        lock (_lock)
        {
            _jobs[job.Id] = job;
        }
    }

    public bool HasActiveJobForApplication(string applicationId)
    {
        lock (_lock)
        {
            return _jobs.Values.Any(j => j.ApplicationId == applicationId && (j.Status == "queued" || j.Status == "running"));
        }
    }
}

using MediaProcessingApi.Dtos;
using MediaProcessingApi.Entities;

namespace MediaProcessingApi.Services;

public class ApplicationService
{
    private readonly InMemoryStore _store;

    public ApplicationService(InMemoryStore store)
    {
        _store = store;
    }

    public (CreateApplicationResponse? response, string? error, int? statusCode) CreateApplication(CreateApplicationRequest request)
    {
        if (request.Type != "photo" && request.Type != "video")
        {
            return (null, "Invalid application type.", 400);
        }

        if (string.IsNullOrWhiteSpace(request.ReferenceFileId) || string.IsNullOrWhiteSpace(request.SourceFileId))
        {
            return (null, "Reference file ID and source file ID are required.", 400);
        }

        var referenceFile = _store.GetFile(request.ReferenceFileId);
        if (referenceFile == null)
        {
            return (null, "Reference file not found.", 400);
        }

        var sourceFile = _store.GetFile(request.SourceFileId);
        if (sourceFile == null)
        {
            return (null, "Source file not found.", 400);
        }

        if (referenceFile.FileRole != "reference")
        {
            return (null, "Reference file must have role 'reference'.", 400);
        }

        if (sourceFile.FileRole != "source")
        {
            return (null, "Source file must have role 'source'.", 400);
        }

        if (request.Type == "photo" && sourceFile.FileType == "mp4")
        {
            return (null, "Photo application requires a photo source file.", 400);
        }

        if (request.Type == "video" && sourceFile.FileType != "mp4")
        {
            return (null, "Video application requires an mp4 source file.", 400);
        }

        var application = new Application
        {
            Type = request.Type,
            ReferenceFileId = request.ReferenceFileId,
            SourceFileId = request.SourceFileId,
            Status = "pending"
        };

        _store.AddApplication(application);

        return (new CreateApplicationResponse
        {
            Id = application.Id,
            Status = application.Status,
            CreatedAt = application.CreatedAt.ToString("o")
        }, null, null);
    }

    public (GetApplicationResponse? response, string? error, int? statusCode) GetApplication(string id)
    {
        var application = _store.GetApplication(id);
        if (application == null)
        {
            return (null, "Application not found.", 404);
        }

        var segments = _store.GetSegmentsByApplicationId(id);
        var resultFileIds = new List<string>();
        if (!string.IsNullOrEmpty(application.ResultFileId))
        {
            resultFileIds.Add(application.ResultFileId);
        }
        foreach (var segment in segments)
        {
            if (!string.IsNullOrEmpty(segment.ResultFileId))
            {
                resultFileIds.Add(segment.ResultFileId);
            }
        }

        return (new GetApplicationResponse
        {
            Id = application.Id,
            Type = application.Type,
            Status = application.Status,
            SimilarityScore = application.SimilarityScore,
            VerificationStatus = application.VerificationStatus,
            ResultFileIds = resultFileIds,
            Segments = segments.Select(s => new SegmentDto
            {
                Id = s.Id,
                StartTime = s.StartTime,
                EndTime = s.EndTime,
                Confidence = s.Confidence,
                ResultFileId = s.ResultFileId
            }).ToList(),
            CreatedAt = application.CreatedAt.ToString("o"),
            UpdatedAt = application.UpdatedAt.ToString("o")
        }, null, null);
    }

    public (TriggerProcessingResponse? response, string? error, int? statusCode) TriggerProcessing(string id)
    {
        var application = _store.GetApplication(id);
        if (application == null)
        {
            return (null, "Application not found.", 404);
        }

        if (application.Status == "processing")
        {
            return (null, "Application is already being processed.", 409);
        }

        if (_store.HasActiveJobForApplication(id))
        {
            return (null, "An active processing job already exists for this application.", 409);
        }

        var jobType = application.Type == "photo" ? "photo_verification" : "video_detection";
        var job = new ProcessingJob
        {
            ApplicationId = application.Id,
            JobType = jobType,
            Status = "queued"
        };

        _store.AddJob(job);

        application.Status = "processing";
        application.UpdatedAt = DateTime.UtcNow;
        _store.UpdateApplication(application);

        return (new TriggerProcessingResponse
        {
            ApplicationId = application.Id,
            JobId = job.Id,
            Status = application.Status
        }, null, null);
    }

    public (GetVideoSegmentsResponse? response, string? error, int? statusCode) GetVideoSegments(string id)
    {
        var application = _store.GetApplication(id);
        if (application == null)
        {
            return (null, "Application not found.", 404);
        }

        var segments = _store.GetSegmentsByApplicationId(id);

        return (new GetVideoSegmentsResponse
        {
            ApplicationId = application.Id,
            Segments = segments.Select(s => new SegmentDto
            {
                Id = s.Id,
                StartTime = s.StartTime,
                EndTime = s.EndTime,
                Confidence = s.Confidence,
                ResultFileId = s.ResultFileId
            }).ToList()
        }, null, null);
    }
}

using MediaProcessingApi.Dtos;
using MediaProcessingApi.Entities;

namespace MediaProcessingApi.Services;

public class FileService
{
    private readonly InMemoryStore _store;

    public FileService(InMemoryStore store)
    {
        _store = store;
    }

    public (GetUploadUrlResponse? response, string? error, int? statusCode) GetUploadUrl(GetUploadUrlRequest request)
    {
        if (request.FileType != "jpeg" && request.FileType != "png" && request.FileType != "mp4")
        {
            return (null, "Invalid file type.", 400);
        }

        if (request.FileRole != "source" && request.FileRole != "reference")
        {
            return (null, "Invalid file role.", 400);
        }

        if (request.SizeBytes <= 0)
        {
            return (null, "File size must be positive.", 400);
        }

        var fileId = Guid.NewGuid().ToString();
        var s3Key = $"uploads/{request.FileRole}/{fileId}.{request.FileType}";
        var expiresAt = DateTime.UtcNow.AddHours(1);

        var file = new MediaFile
        {
            Id = fileId,
            S3Key = s3Key,
            FileType = request.FileType,
            FileRole = request.FileRole,
            SizeBytes = request.SizeBytes,
            Status = "pending"
        };

        _store.AddFile(file);

        return (new GetUploadUrlResponse
        {
            FileId = fileId,
            UploadUrl = $"https://s3.amazonaws.com/bucket/{s3Key}?X-Amz-Expires=3600&X-Amz-Signature=mock",
            S3Key = s3Key,
            ExpiresAt = expiresAt.ToString("o")
        }, null, null);
    }

    public (ConfirmFileUploadResponse? response, string? error, int? statusCode) ConfirmFileUpload(string id)
    {
        var file = _store.GetFile(id);
        if (file == null)
        {
            return (null, "File not found.", 404);
        }

        file.Status = "confirmed";
        _store.UpdateFile(file);

        return (new ConfirmFileUploadResponse
        {
            FileId = file.Id,
            Status = file.Status
        }, null, null);
    }

    public (GetDownloadUrlResponse? response, string? error, int? statusCode) GetDownloadUrl(string id)
    {
        var file = _store.GetFile(id);
        if (file == null)
        {
            return (null, "File not found.", 404);
        }

        var expiresAt = DateTime.UtcNow.AddHours(1);

        return (new GetDownloadUrlResponse
        {
            FileId = file.Id,
            DownloadUrl = $"https://s3.amazonaws.com/bucket/{file.S3Key}?X-Amz-Expires=3600&X-Amz-Signature=mock",
            ExpiresAt = expiresAt.ToString("o")
        }, null, null);
    }
}

using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using MediaProcessingApi.Dtos;
using MediaProcessingApi.Services;

namespace MediaProcessingApi.Controllers;

[ApiController]
[Route("applications")]
[Authorize]
public class ApplicationsController : ControllerBase
{
    private readonly ApplicationService _applicationService;

    public ApplicationsController(ApplicationService applicationService)
    {
        _applicationService = applicationService;
    }

    [HttpPost]
    public IActionResult CreateApplication([FromBody] CreateApplicationRequest request)
    {
        var (response, error, statusCode) = _applicationService.CreateApplication(request);
        if (error != null)
        {
            return Problem(new ProblemDetails
            {
                Type = "https://httpstatuses.io/400",
                Title = "Bad Request",
                Status = statusCode ?? 400,
                Detail = error
            });
        }

        return CreatedAtAction(nameof(GetApplication), new { id = response.Id }, response);
    }

    [HttpGet("{id}")]
    public IActionResult GetApplication(string id)
    {
        var (response, error, statusCode) = _applicationService.GetApplication(id);
        if (error != null)
        {
            return Problem(new ProblemDetails
            {
                Type = "https://httpstatuses.io/404",
                Title = "Not Found",
                Status = statusCode ?? 404,
                Detail = error
            });
        }

        return Ok(response);
    }

    [HttpPost("{id}/process")]
    public IActionResult TriggerProcessing(string id)
    {
        var (response, error, statusCode) = _applicationService.TriggerProcessing(id);
        if (error != null)
        {
            var title = statusCode == 409 ? "Conflict" : "Not Found";
            var type = statusCode == 409 ? "https://httpstatuses.io/409" : "https://httpstatuses.io/404";
            return Problem(new ProblemDetails
            {
                Type = type,
                Title = title,
                Status = statusCode ?? 404,
                Detail = error
            });
        }

        return Ok(response);
    }

    [HttpGet("{id}/segments")]
    public IActionResult GetVideoSegments(string id)
    {
        var (response, error, statusCode) = _applicationService.GetVideoSegments(id);
        if (error != null)
        {
            return Problem(new ProblemDetails
            {
                Type = "https://httpstatuses.io/404",
                Title = "Not Found",
                Status = statusCode ?? 404,
                Detail = error
            });
        }

        return Ok(response);
    }
}

